<script>let {release,compact=false}=$props();const size=b=>b?Math.round(b/1024/1024)+' MB':'';</script>
<section class:compact class="release-panel"><div class="release-about"><p class="eyebrow">{release.preview?'PREVIEW RELEASE':'PUBLISHED RELEASE'}</p><h2>{release.name}</h2><p class="hint">Published {new Date(release.date).toLocaleDateString()}</p></div><div class="site-actions"><a class="tool primary" href={release.mod.browser_download_url}>Download mod{compact?'':' · '+size(release.mod.size)}</a><a class="tool" href={release.engine.browser_download_url}>Required engine{compact?'':' · '+size(release.engine.size)}</a><a class="tool" href="#help">Installation guide</a></div>{#if release.bodycam}<div class="card"><h3>Optional Bodycam engine</h3><p class="hint">DX11-AVX only. Use instead of the standard engine, with both bin and db/mods from the ZIP.</p><a class="tool" href={release.bodycam.browser_download_url}>Download Bodycam engine · {size(release.bodycam.size)}</a></div>{/if}<p class="release-note">Install the mod and its matching engine. Existing 2.0.x saves work with 2.0.3.</p>{#if release.tag==='v2.0.3'}<p class="release-note">Select the optional Mags Reloaded ammo fix in the FOMOD with Mags Reloaded Fork by Priler UPDATE 6 and its Dynamic Reload Speeds dependency installed. It requires the 2.0.3 engine. Let Squared Away win their file conflicts in MO2.</p>{/if}{#if !compact}<details class="release-notes"><summary>Release notes</summary><div class="release-notes-text">{release.notes}</div></details>{/if}</section>
